{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 2 * 10^5",
      "description": "The number of videos Monocarp wants to watch is at least 1 and at most 2 * 10^5."
    },
    {
      "id": "P2",
      "expression": "1 <= m <= 10^9",
      "description": "The size of the hard disk is at least 1 and at most 10^9."
    },
    {
      "id": "P3",
      "expression": "1 <= a_i <= m",
      "description": "Each video size is at least 1 and at most the size of the hard disk."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == sum(max(a_i, (m + sum(a_j) - a_i) // n) for i in range(n))",
      "description": "The output is the minimum time required to watch all videos, calculated by summing the maximum of each video's download time and the time needed to free up space for the next video."
    }
  ],
  "invariants": []
}
